const MARKS = `<p>Знак огибают <b>левым бортом</b> — значит, знак всё время у тебя слева (яхта идёт вокруг против часовой стрелки). <b>Правым бортом</b> — знак справа.</p>
  <p><b>Наветренный знак</b> — против ветра от старта. <b>Отбойник</b> — небольшой знак рядом с ним, огибается следом. <b>Ворота</b> — два знака: можно огибать любой, выбирай выгодный. <b>Финиш</b> — линия между комитетом с синим флагом и знаком.</p>
  <p>На маршрутных гонках знаками бывают острова, мысы и буи: «остров Гёчек правым бортом» — остров остаётся справа.</p>${D.r18}`;

const SAFETY = `<p><b>Одна рука — себе, другая — яхте.</b> На палубе всегда держись за леер, ванты или поручень. Передвигайся по наветренному борту, пригнувшись. В волну, в свежий ветер и ночью — страховочный пояс и привязь.</p>
  <p><b>Спасжилет.</b> Когда комитет поднимает флаг Y — обязательно всем. В свежий ветер и в холодной воде — всегда. У автоматического жилета проверяй баллончик.</p>
  <p><b>Гик.</b> При фордевинде гик перелетает через кокпит с большой силой. Головы ниже гика, предупреждай командой «Фордевинд!».</p>
  <p><b>Человек за бортом.</b> 1) Сразу громко «Человек за бортом!». 2) Один человек всё время смотрит на упавшего и показывает на него рукой — его нельзя терять из виду. 3) Брось спасательный круг или подкову. 4) Отметь точку на картплоттере (кнопка MOB). 5) Разворачивайся сразу и подходи к человеку против ветра на малом ходу, чтобы остановиться рядом. Двигатель — только если винт далеко от человека.</p>
  <p><b>Мели.</b> Наша осадка 2,2 м. Приложение предупреждает о мели по курсу и показывает известные опасности (например, мель южнее кардинального буя у Гёчека), но модель глубин приблизительная — сверяйся с навигационной картой.</p>
  <p><b>Ветер.</b> Перед выходом проверь прогноз. Если ветер усиливается — рифимся заранее, а не когда уже тяжело.</p>`;

const APP = `<h3>Подготовка</h3>
  <p><b>1. Регата.</b> На первом экране выбери регату — карта перейдёт в нужный район.</p>
  <p><b>2. Дистанция.</b> Вкладка «Маршрут»: выбери дистанцию из гоночной инструкции и нажми «Загрузить». Для наветренно-подветренных введи азимут на знак, который объявил комитет (дистанцию можно не вводить — знак встанет на 1 милю и на огибании уточнится сам). Маршрут рисуется цветом от синего (старт) к фиолетовому (финиш).</p>
  <p><b>3. Линия старта.</b> На воде подойди к пину и к комитету и у каждого <b>удерживай</b> «Пинг пин» / «Пинг комитет» — записывается позиция GPS планшета. Простое нажатие не срабатывает (защита от случайного).</p>
  <p><b>4. Таймер.</b> По первому сигналу нажми «Старт / синхр.». На следующих сигналах можно нажать ещё раз — таймер подгонится к ровной минуте (только если нажатие в пределах ±10 с от минуты).</p>
  <h3>Как считается старт</h3>
  <p><b>До линии</b> — расстояние от <i>носа</i> до линии по перпендикуляру. Нос считается от антенны планшета вперёд на расстояние из настроек («GPS → нос», по умолчанию 7 м).</p>
  <p><b>Время до линии</b> — сколько секунд нужно, чтобы дойти до линии на полной скорости по поляре: если ты уже идёшь к линии — текущим курсом, если нет — бейдевиндом нужного галса. Добавляется время на разгон (настройка «Разгон, с») и на разворот, если надо повернуть больше чем на 30°.</p>
  <p><b>Запас</b> = время до старта − время до линии. Больше 15 с — «РАНО, жги»; 3–15 с — «ЗАПАС»; около нуля — «В ТАЙМИНГ, полный ход»; меньше нуля — «ОПАЗДЫВАЕМ».</p>
  <p><b>Выгодный конец</b> — какой конец линии ближе к ветру и на сколько метров. <b>Пересечём</b> — в каком месте линии (в % от пина) окажемся, если идти текущим курсом.</p>
  <p><b>Фальстарт</b>: если в момент старта нос за линией — звучит «Фальстарт», надо вернуться. Пересёк линию после сигнала — «Стартовали», приложение переходит на «Гонку».</p>
  <h3>Как считается ветер</h3>
  <p>Датчиков ветра нет, поэтому ветер вычисляется по курсам GPS. Приложение находит устойчивые участки курса (не меньше 20 секунд ровно), различает повороты оверштаг и фордевинд по углу поворота и скорости, а затем берёт <b>середину между курсами правого и левого галса</b> — это и есть направление ветра. Последние минуты весят больше, поэтому сдвиги видны. Сила ветра оценивается по углу поворота и по скорости лодки относительно поляры. До первых поворотов используется объявленный азимут на знак или прогноз — тогда у значения стоит «≈».</p>
  <h3>Как считается гонка</h3>
  <p><b>Пеленг, дистанция</b> — до следующего знака. <b>Будем на знаке</b> — время прихода: на лавировке считается путь двумя галсами под углом бейдевинда по поляре, на попутном — галсами фордевинда, на галфвинде — прямо.</p>
  <p><b>Лейлайны</b> рисуются от знака под углом бейдевинда плюс 3° на дрейф. «До лейлайна» — сколько идти текущим галсом до поворота; «лежим на знак» — уже можно не поворачивать; «перебрали» — прошли лейлайн.</p>
  <p><b>Поляра</b> — сравнение скорости с таблицей ORC однотипной лодки при текущем ветре; появляется, когда ветер оценён по поворотам. <b>Сдвиг на галсе</b> — насколько текущий курс выше или ниже среднего курса этого галса: «заходит» (подъём) или «отходит».</p>
  <p><b>Знаки</b> переключаются сами: при проходе рядом и смене курса. Острова огибаются по точкам вокруг них, маршрут обходит сушу по воде.</p>
  <h3>Глубины и мели</h3>
  <p>Карта глубин — модель по данным EMODnet/GEBCO и береговой линии OpenStreetMap: у берега глубина сводится к нулю. «Мелко впереди» звучит, только когда идёшь быстрее 1,5 узла, под тобой глубоко, а через 2 минуты хода — меньше 5 м. Известные мели (например, у кардинального буя в Гёчеке) отмечены красными зонами. Модель приблизительная — для навигации нужна настоящая карта.</p>
  <h3>Без интернета</h3>
  <p>Приложение целиком сохраняется в браузере при первом открытии и дальше работает офлайн: карта, глубины, дистанции, учебник. Интернет нужен только для прогноза и для онлайн-подложек OSM и спутника.</p>`;


// ---------------------------------------------------------------- stern view (to scale, 30 px/m)
function sternView() {
  const S = 30, CX = 330, WL = 560;
  const x = (m) => CX + m * S, y = (h) => WL - h * S;
  const f = (v) => v.toFixed(1);
  const deck = 1.30, transomTop = 1.22, mastTop = 16.92, hounds = deck + 14.14, spLo = deck + 5.7, spHi = deck + 10.4;
  const half = 1.805, chainplate = 1.55;
  const hull = `M${f(x(-half))},${f(y(deck))} L${f(x(-1.74))},${f(y(0.28))} C${f(x(-1.6))},${f(y(-0.18))} ${f(x(-0.7))},${f(y(-0.43))} ${f(x(0))},${f(y(-0.44))}`
    + ` C${f(x(0.7))},${f(y(-0.43))} ${f(x(1.6))},${f(y(-0.18))} ${f(x(1.74))},${f(y(0.28))} L${f(x(half))},${f(y(deck))} Z`;
  const transom = `M${f(x(-1.72))},${f(y(transomTop))} L${f(x(1.72))},${f(y(transomTop))} L${f(x(1.5))},${f(y(0.2))} L${f(x(-1.5))},${f(y(0.2))} Z`;
  const shroud = (sg) => `M${f(x(0.03 * sg))},${f(y(hounds))} L${f(x(0.6 * sg))},${f(y(spHi))} L${f(x(0.85 * sg))},${f(y(spLo))} L${f(x(chainplate * sg))},${f(y(deck))}`
    + ` M${f(x(0.03 * sg))},${f(y(spHi))} L${f(x(0.83 * sg))},${f(y(spLo))} L${f(x(chainplate * sg - 0.04))},${f(y(deck))}`
    + ` M${f(x(0.03 * sg))},${f(y(spLo - 0.15))} L${f(x(chainplate * sg - 0.08))},${f(y(deck))}`;
  const wheel = (cx) => {
    const r = 0.47 * S, cy = y(deck + 0.36);
    return `<g clip-path="url(#svDeck)"><line x1="${f(cx)}" y1="${f(cy)}" x2="${f(cx)}" y2="${f(y(deck - 0.2))}" stroke="#8e9daa" stroke-width="3"/>`
      + [0, 60, 120].map((a) => `<line x1="${f(cx + r * Math.cos(a * Math.PI / 180))}" y1="${f(cy + r * Math.sin(a * Math.PI / 180))}" x2="${f(cx - r * Math.cos(a * Math.PI / 180))}" y2="${f(cy - r * Math.sin(a * Math.PI / 180))}" stroke="#b7c4cf" stroke-width="1.2"/>`).join('')
      + `<circle cx="${f(cx)}" cy="${f(cy)}" r="${f(r)}" fill="none" stroke="#d3dce4" stroke-width="2.2"/><circle cx="${f(cx)}" cy="${f(cy)}" r="2.5" fill="#d3dce4"/></g>`;
  };
  const winch = (cx) => `<path d="M${f(cx - 4)},${f(y(deck + 0.05))} L${f(cx - 3)},${f(y(deck + 0.24))} L${f(cx + 3)},${f(y(deck + 0.24))} L${f(cx + 4)},${f(y(deck + 0.05))} Z" fill="#c9d3dc"/><rect x="${f(cx - 3.5)}" y="${f(y(deck + 0.3))}" width="7" height="2.5" fill="#2b3640"/>`;
  const L = [
    ['Краспицы', x(0.85), y(spLo)], ['Топовые ванты', x(-0.6), y(9.4)], ['Нижние ванты', x(-0.95), y(4.2)],
    ['Ахтерштаг', x(0.45), y(3.0)], ['Штурвалы', x(0.75), y(deck + 0.85)], ['Кормовой релинг', x(-1.6), y(deck + 0.62)],
    ['Путенс', x(chainplate), y(deck)], ['Лебёдка', x(-1.25), y(deck + 0.22)], ['Палуба', x(-1.1), y(transomTop - 0.1)],
    ['Скула', x(-1.74), y(0.28)], ['Бульб', x(0.25), y(-2.03)],
  ];
  const labels = callouts(L, 150, 520, CX, 26, 14);
  return `<svg class="lsvg lstern" viewBox="0 0 680 680" role="img" aria-label="Вид NORD STAR с кормы">
    <defs><clipPath id="svDeck"><rect x="0" y="0" width="680" height="${f(y(transomTop))}"/></clipPath></defs>
    <rect width="680" height="680" fill="#071523"/>
    <rect x="0" y="${WL}" width="680" height="${680 - WL}" fill="#0b2a40" opacity="0.8"/>
    <line x1="20" y1="${WL}" x2="660" y2="${WL}" stroke="#2c6b94" stroke-dasharray="6 4"/><text x="656" y="${WL - 5}" font-size="11" fill="#4f8fb8" text-anchor="end">ватерлиния</text>
    <g stroke="#9db4c6" fill="none" stroke-width="1.1">${shroud(-1)}${shroud(1)}</g>
    <path d="M${f(x(0))},${f(y(mastTop))} L${f(x(0))},${f(y(deck + 2.4))} M${f(x(0))},${f(y(deck + 2.4))} L${f(x(-1.2))},${f(y(transomTop))} M${f(x(0))},${f(y(deck + 2.4))} L${f(x(1.2))},${f(y(transomTop))}" stroke="#9db4c6" stroke-width="1.1" fill="none"/>
    <rect x="${f(x(-0.09))}" y="${f(y(mastTop))}" width="${f(0.18 * S)}" height="${f((mastTop - deck) * S)}" fill="#c3ced7"/>
    <g stroke="#c3ced7" stroke-width="2.4" stroke-linecap="round"><line x1="${f(x(-0.85))}" y1="${f(y(spLo))}" x2="${f(x(0.85))}" y2="${f(y(spLo))}"/><line x1="${f(x(-0.6))}" y1="${f(y(spHi))}" x2="${f(x(0.6))}" y2="${f(y(spHi))}"/></g>
    <rect x="${f(x(-0.11))}" y="${f(y(deck + 1.72))}" width="${f(0.22 * S)}" height="${f(0.16 * S)}" rx="2" fill="#b9c5cf"/>
    <rect x="${f(x(-0.95))}" y="${f(y(deck + 0.25))}" width="${f(1.9 * S)}" height="${f(0.25 * S)}" rx="3" fill="#e3e9ef" opacity="0.8"/>
    <path d="${hull}" fill="#e9eef3" stroke="#8ea6b9"/>
    <path d="M${f(x(-1.73))},${f(y(0))} L${f(x(1.73))},${f(y(0))} L${f(x(1.65))},${f(y(-0.2))} C${f(x(1.2))},${f(y(-0.4))} ${f(x(-1.2))},${f(y(-0.4))} ${f(x(-1.65))},${f(y(-0.2))} Z" fill="#162f46"/>
    <path d="M${f(x(-0.06))},${f(y(-0.3))} L${f(x(0.06))},${f(y(-0.3))} L${f(x(0.05))},${f(y(-1.86))} L${f(x(-0.05))},${f(y(-1.86))} Z" fill="#5b7fa3" stroke="#a9c8e6"/>
    <ellipse cx="${f(x(0))}" cy="${f(y(-2.03))}" rx="${f(0.24 * S)}" ry="${f(0.17 * S)}" fill="#5b7fa3" stroke="#a9c8e6"/>
    <path d="${transom}" fill="#f7f9fb" stroke="#8ea6b9"/>
    <path d="M${f(x(-1.0))},${f(y(0.75))} L${f(x(1.0))},${f(y(0.75))}" stroke="#26323d" stroke-width="3"/>
    <text x="${f(x(0))}" y="${f(y(0.48))}" text-anchor="middle" font-size="12" font-weight="800" letter-spacing="1.5" fill="#26323d">NORD STAR</text>
    <path d="M${f(x(-0.04))},${f(y(0.18))} L${f(x(0.04))},${f(y(0.18))} L${f(x(0.03))},${f(y(-1.62))} L${f(x(-0.03))},${f(y(-1.62))} Z" fill="#6f93b8" stroke="#b9d4ec"/>
    ${wheel(x(-0.75))}${wheel(x(0.75))}${winch(x(-1.25))}${winch(x(1.25))}
    <g stroke="#9db4c6" stroke-width="1.6" fill="none"><path d="M${f(x(-1.62))},${f(y(transomTop))} V${f(y(deck + 0.62))} H${f(x(-0.55))}"/><path d="M${f(x(1.62))},${f(y(transomTop))} V${f(y(deck + 0.62))} H${f(x(0.55))}"/>
      <line x1="${f(x(-1.79))}" y1="${f(y(deck))}" x2="${f(x(-1.79))}" y2="${f(y(deck + 0.62))}"/><line x1="${f(x(1.79))}" y1="${f(y(deck))}" x2="${f(x(1.79))}" y2="${f(y(deck + 0.62))}"/></g>
    <g stroke="#5fa8d3" stroke-width="0.9" fill="none"><line x1="${f(x(-half))}" y1="640" x2="${f(x(half))}" y2="640"/><line x1="${f(x(-half))}" y1="634" x2="${f(x(-half))}" y2="646"/><line x1="${f(x(half))}" y1="634" x2="${f(x(half))}" y2="646"/>
      <line x1="${f(x(2.6))}" y1="${WL}" x2="${f(x(2.6))}" y2="${f(y(-2.2))}"/><line x1="${f(x(2.45))}" y1="${f(y(-2.2))}" x2="${f(x(2.75))}" y2="${f(y(-2.2))}"/>
      <line x1="${f(x(2.6))}" y1="${WL}" x2="${f(x(2.6))}" y2="${f(y(deck))}"/></g>
    <g font-size="12" fill="#8fc3e6" font-family="ui-monospace,Menlo,monospace"><text x="${f(x(0))}" y="660" text-anchor="middle">ширина B 3.61 м</text>
      <text x="${f(x(2.7))}" y="${f(y(-1.2))}">осадка T 2.20</text><text x="${f(x(2.7))}" y="${f(y(0.55))}">надводный борт ~1.3</text></g>
    ${labels}
  </svg>`;
}

